    <div class="tw" style="margin-top:14px"><table><thead><tr>${opts.interactive ? '<th></th>' : ''}<th>Descrizione</th><th>Un.</th><th class="right">Q.tà</th><th class="right">Prezzo</th><th class="right">Totale</th></tr></thead><tbody>${o.capitolato.map((r, i) => { const isOpt = opz.includes(i); const on = !isOpt || sel[i] !== false; return `<tr style="${!on ? 'opacity:.45' : ''}">${opts.interactive ? `<td>${isOpt ? `<input type="checkbox" data-firma-opt="${i}" ${on ? 'checked' : ''} aria-label="Opzione">` : ''}</td>` : ''}<td class="wrap">${esc(r[1])}${isOpt ? ' <span class="pill info">opzionale</span>' : ''}</td><td>${r[2]}</td><td class="right num">${n0(r[3])}</td><td class="right num">${n2(r[4])}</td><td class="right num">${n2(r[3] * r[4])}</td></tr>`; }).join('')}</tbody></table></div>
