function sigSave() { const c = document.getElementById('sigpad'); if (c && S.firma && S.firma.has) S.firma.img = c.toDataURL('image/png'); }

// ---------- eventi aggiuntivi ----------
document.addEventListener('click', (e) => { const el = e.target.closest('[data-act="prof-toggle"]'); if (el) { const pos = el.dataset.pos || 'top'; if (S.profOpen && S.profPos !== pos) S.profOpen = false; S.profPos = pos; } }, true);
document.addEventListener('click', (e) => {
  const el = e.target.closest('[data-act]'); if (!el) return; const act = el.dataset.act, id = el.dataset.id; const ds = el.dataset; const F = S.firma;
  const A = {
    'view-cant': () => { S.sel.viewCant = id; render(); }, 'view-off': () => { S.sel.viewOff = id; render(); },
    'kan-move': () => { kanMove(ds.kind, id, ds.to); render(); },
    'off-mode': () => { if (id === 'ia-reset') { S.modal.aiDone = false; S.modal.ai = null; S.modal.mode = 'ia'; } else S.modal.mode = id; render(); },
    'off-sample': () => { S.modal.desc = AI_OFF_SAMPLES[+id]; render(); },
    'off-ai': () => { const m = S.modal; m.aiScan = true; render(); setTimeout(() => { if (!S.modal || S.modal.type !== 'offerta-new') return; const r = aiOfferta(m.desc, null); m.aiScan = false; m.aiDone = true; m.ai = r; m.rows = r.rows.length ? r.rows : m.rows; m.tipo = r.tipo; if (!m.oggetto) { const k = cliente(m.clienteId); m.oggetto = (k.nome.split(' ').slice(-1)[0] + ': ' + m.desc.split(/[.,:]/)[0]).slice(0, 80); } render(); toast(r.rows.length ? r.rows.length + ' posizioni proposte: controlla quantità e prezzi' : 'Non ho riconosciuto lavorazioni: descrivi meglio il lavoro'); }, 1600); },
    'acconti-edit': () => { S.modal = { type: 'acconti', id }; render(); },
    'acc-row-add': () => { S.modal.rows.push({ pct: 10, quando: 'A fine lavori' }); render(); }, 'acc-row-del': () => { S.modal.rows.splice(+id, 1); render(); },
    'acconti-save': () => { const o = offerta(S.modal.id); o.acconti = S.modal.rows.map((r) => ({ pct: +r.pct, quando: r.quando })); S.modal = null; toast('Piano acconti salvato'); },
    'fwiz-rata': () => { const [oid, i] = id.split('|'); S.modal = { type: 'fwiz', offertaId: oid, tipo: 'Acconto', rata: +i, pct: offerta(oid).acconti[+i].pct }; render(); },
    'create-link': () => { S.modal = { type: 'offerta-link', id }; render(); },
    'copy-link': () => { const o = offerta(id); try { navigator.clipboard.writeText(linkUrl(o)); } catch (_) {} toast('Link copiato: ' + linkUrl(o)); },
    'open-firma': () => { const o = offerta(id); ensureLink(o); S.firma = { token: o.link.token, phase: 'gate', email: '', sel: {}, tab: 'draw', name: '', place: '', date: D.TODAY_ISO }; go('firma', o.link.token); },
    'firma-office': () => { const o = offerta(id); ensureLink(o); const k = cliente(o.clienteId); S.firma = { token: o.link.token, oid: o.id, phase: 'ready', email: o.link.email, sel: {}, tab: 'draw', name: k.contatto, place: k.comune, date: D.TODAY_ISO, signOpen: true }; logEv(o, 'access', 'Aperta in ufficio con il cliente (tablet)'); go('firma', o.link.token); },
    'sig-open': () => { F.signOpen = true; F.name = F.name || cliente(offerta(F.oid).clienteId).contatto; render(); },
    'sig-close': () => { sigSave(); F.signOpen = false; render(); },
    'sig-tab': () => { sigSave(); F.tab = id; render(); },
    'sig-clear': () => { const c = document.getElementById('sigpad'); if (c) c.getContext('2d').clearRect(0, 0, c.width, c.height); F.has = false; F.img = ''; render(); },
    'sig-confirm': () => { sigSave(); if (!F.name.trim()) return toast('Scrivi nome e cognome'); if (!F.consent) return toast('Conferma di aver letto e accettato l\'offerta'); if (F.tab === 'draw' && !F.has) return toast('Disegna la firma o scegli "Digita il nome"'); F.confirm = true; render(); },
    'sig-back': () => { F.confirm = false; render(); },
    'sig-do': () => { const o = offerta(F.oid); const img = F.tab === 'draw' ? F.img : typedSig(F.name); const esclusi = (o.opzionali || []).filter((i) => F.sel[i] === false); applySign(o, { firmatario: F.name, luogo: F.place || cliente(o.clienteId).comune, img, metodo: F.tab === 'draw' ? 'Firma elettronica (SES), disegnata' : 'Firma elettronica (SES), nome digitato', totale: Math.round(offSelTotal(o, F.sel)), esclusi, email: F.email }); F.confirm = false; F.signOpen = false; F.done = true; render(); },
    'sig-done-close': () => { F.done = false; render(); },
    'firma-download': () => { const o = offerta(F.oid); logEv(o, 'download', 'PDF scaricato' + ((o.opzionali || []).some((i) => F.sel[i] === false) ? ' senza alcune opzioni' : ''), F.email); S.modal = { type: 'print', kind: 'offerta', id: o.id }; render(); setTimeout(() => window.print(), 300); },
  };
  if (A[act]) { e.preventDefault(); A[act](); }
});
document.addEventListener('submit', (e) => {
  const f = e.target.closest('form[data-act]'); if (!f) return; const act = f.dataset.act;
  if (act === 'firma-gate') { e.preventDefault(); const o = DB.offerte.find((x) => x.link && x.link.token === S.id); const em = f.email.value.trim().toLowerCase(); if (!o || em !== o.link.email.toLowerCase()) { toast('E-mail non autorizzata per questa offerta'); return; } S.firma.email = em; S.firma.phase = 'ready'; S.firma.oid = o.id; S.firma.name = cliente(o.clienteId).contatto; S.firma.place = cliente(o.clienteId).comune; logEv(o, 'access', 'Aperta dal cliente', em); render(); }
  if (act === 'link-create') { e.preventDefault(); const o = offerta(S.modal.id); const em = f.email.value.trim(); o.link = { token: Math.random().toString(16).slice(2, 8) + '-' + o.id.slice(-4), email: em, creato: nowISO() }; if (!o.eventi) o.eventi = []; logEv(o, 'link', 'Link creato per ' + em, em); S.modal = null; toast('Link creato: ora puoi inviarlo o copiarlo'); render(); }
});
document.addEventListener('change', (e) => {
  const t = e.target; const ds = t.dataset; const m = S.modal;
  if (ds.firmaOpt != null) { S.firma.sel[+ds.firmaOpt] = t.checked; render(); return; }
  if (ds.sig === 'consent') { S.firma.consent = t.checked; return; }
  if (ds.accRow && m) { const [i, k] = ds.accRow.split('|'); m.rows[+i][k] = k === 'pct' ? +t.value : t.value; render(); return; }
  if (ds.actChange === 'off-add-listino' && m && t.value) { const p = LISTINO.find((x) => x.npk === t.value); m.rows.push({ pos: 'NPK ' + p.npk, desc: p.desc, un: p.un, qta: 0, prezzo: p.prezzo, fonte: p.n + ' offerte' }); t.value = ''; render(); return; }
  if (ds.actChange === 'off-plan' && m) { const n = t.files.length; m.plan = n + (n === 1 ? ' file letto' : ' file letti') + ': 118 m² calpestabili, 7 locali, h 2.6 m'; m.desc = (m.desc || '') + (m.desc ? ' ' : '') + 'Dalla planimetria: 118 m², 7 locali, altezza 2.6 m.'; render(); return; }
  if (ds.actChange === 'link-contact' && m) { m.email = t.value; render(); return; }
});
document.addEventListener('input', (e) => { const ds = e.target.dataset; if (ds.sig && S.firma) { if (ds.sig === 'name') S.firma.name = e.target.value; if (ds.sig === 'place') S.firma.place = e.target.value; if (ds.sig === 'date') S.firma.date = e.target.value; } if (ds.accRow && S.modal) { const [i, k] = ds.accRow.split('|'); S.modal.rows[+i][k] = k === 'pct' ? +e.target.value : e.target.value; } });
// voce per la descrizione dell'offerta
VOICE_SAMPLES.off = AI_OFF_SAMPLES;
// pad di firma: pointer events
let _drawing = false;
const padPos = (c, e) => { const r = c.getBoundingClientRect(); return { x: (e.clientX - r.left) * (c.width / r.width), y: (e.clientY - r.top) * (c.height / r.height) }; };
document.addEventListener('pointerdown', (e) => { const c = e.target.closest && e.target.closest('#sigpad'); if (!c) return; e.preventDefault(); _drawing = true; const x = c.getContext('2d'); const p = padPos(c, e); x.beginPath(); x.moveTo(p.x, p.y); try { c.setPointerCapture(e.pointerId); } catch (_) {} });
document.addEventListener('pointermove', (e) => { if (!_drawing) return; const c = document.getElementById('sigpad'); if (!c) return; const x = c.getContext('2d'); const p = padPos(c, e); x.lineTo(p.x, p.y); x.stroke(); if (S.firma && !S.firma.has) { S.firma.has = true; } });
document.addEventListener('pointerup', () => { if (_drawing) { _drawing = false; sigSave(); const s = document.querySelector('.sigpad + .row .small'); if (s) s.innerHTML = I('check') + ' firma tracciata'; } });
// drag & drop kanban
document.addEventListener('dragstart', (e) => { const k = e.target.closest && e.target.closest('.kcard'); if (!k) return; S._drag = { id: k.dataset.drag, kind: k.dataset.kind }; k.classList.add('dragging'); try { e.dataTransfer.setData('text/plain', k.dataset.drag); e.dataTransfer.effectAllowed = 'move'; } catch (_) {} });
document.addEventListener('dragend', (e) => { const k = e.target.closest && e.target.closest('.kcard'); if (k) k.classList.remove('dragging'); document.querySelectorAll('.kcol.over').forEach((x) => x.classList.remove('over')); });
document.addEventListener('dragover', (e) => { const col = e.target.closest && e.target.closest('.kcol'); if (!col || !S._drag || col.dataset.kind !== S._drag.kind) return; e.preventDefault(); col.classList.add('over'); });
document.addEventListener('dragleave', (e) => { const col = e.target.closest && e.target.closest('.kcol'); if (col) col.classList.remove('over'); });
document.addEventListener('drop', (e) => { const col = e.target.closest && e.target.closest('.kcol'); if (!col || !S._drag) return; e.preventDefault(); const d = S._drag; S._drag = null; kanMove(d.kind, d.id, col.dataset.drop); render(); });
